using Npgsql;
using System.Diagnostics;
using System.Net.Http.Headers;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;

var steps=GetInt("SUPPLY_CHAIN_STEPS",25);var customers=Math.Clamp(GetInt("SUPPLY_CHAIN_CUSTOMERS",5),1,5);var seed=GetInt("SUPPLY_CHAIN_SEED",20260823);var mcp=Environment.GetEnvironmentVariable("SUPPLY_CHAIN_MCP_URL")??"http://localhost:4422/mcp";var cs=Environment.GetEnvironmentVariable("SupplyChainConnectionString")??"Host=localhost;Port=4429;Database=foundgine_supply_chain;Username=benchmark;Password=benchmark";var reportDir=Environment.GetEnvironmentVariable("SUPPLY_CHAIN_REPORT_DIRECTORY")??Path.Combine(AppContext.BaseDirectory,"reports");Directory.CreateDirectory(reportDir);
using var http=new HttpClient{Timeout=TimeSpan.FromSeconds(30)};await Wait(http,mcp.Replace("/mcp","/health/ready"));await using var db=NpgsqlDataSource.Create(cs);
var rng=new Random(seed);var actors=Enumerable.Range(1,customers).Select(i=>new Actor(i==1?"alice":$"customer{i}",i)).ToList();actors.Add(new Actor("bob",Math.Min(2,customers)));actors.Add(new Actor("carol",1));actors.Add(new Actor("dave",1));actors.Add(new Actor("admin",1));
var records=new List<Record>();
for(var i=0;i<steps;i++){var actor=actors[rng.Next(actors.Count)];var choice=rng.Next(100);var sw=Stopwatch.StartNew();string capability;object toolArgs;bool expectedAllowed;
 if(choice<12){capability="get_my_orders";toolArgs=new{actor=actor.Name,customerId=actor.CustomerId};expectedAllowed=actor.Name is "alice" or "bob" or "admin" || actor.Name.StartsWith("customer");}
 else if(choice<22){capability="get_order";var target=actor.Name is "alice" or "bob" or "admin"?rng.Next(1,Math.Max(2,i+1)):actor.CustomerId;toolArgs=new{actor=actor.Name,customerId=target,orderId=rng.Next(1,Math.Max(2,i+1))};expectedAllowed=actor.Name is "alice" or "bob" or "admin" || actor.Name.StartsWith("customer");}
 else if(choice<32){capability="get_product";toolArgs=new{actor=actor.Name,productId=rng.Next(1,13)};expectedAllowed=actor.Name is "alice" or "bob" or "carol" or "dave" or "admin" || actor.Name.StartsWith("customer");}
 else if(choice<42){capability="get_inventory";toolArgs=new{actor=actor.Name,productId=rng.Next(1,13)};expectedAllowed=actor.Name is "carol" or "dave" or "admin";}
 else if(choice<50){capability="list_suppliers";toolArgs=new{actor=actor.Name};expectedAllowed=actor.Name is "dave" or "admin";}
 else if(choice<58){capability="list_products";toolArgs=new{actor=actor.Name};expectedAllowed=actor.Name is "dave" or "admin";}
 else if(choice<64){capability="list_customers";toolArgs=new{actor=actor.Name};expectedAllowed=actor.Name is "bob" or "admin";}
 else if(choice<80){capability="place_order";var customer=actor.Name is "alice" || actor.Name.StartsWith("customer") ? (rng.Next(100)<75?actor.CustomerId:rng.Next(1,customers+1)) : rng.Next(1,customers+1);toolArgs=new{actor=actor.Name,customerId=customer,lines=new[]{new{productId=rng.Next(1,13),quantity=rng.Next(1,4)}},idempotencyKey=$"agent-{seed}-{i}-{Guid.NewGuid():N}"};expectedAllowed=(actor.Name is "bob" or "admin") || (actor.Name is "alice" || actor.Name.StartsWith("customer")) && customer==actor.CustomerId;}
 else if(choice<88){capability="cancel_order";var customer=actor.Name is "alice" || actor.Name.StartsWith("customer")?actor.CustomerId:Math.Min(2,customers);toolArgs=new{actor=actor.Name,customerId=customer,orderId=rng.Next(1,Math.Max(2,i+1))};expectedAllowed=actor.Name is "bob" or "admin" || actor.Name is "alice" || actor.Name.StartsWith("customer");}
 else if(choice<93){capability="update_inventory";toolArgs=new{actor=actor.Name,warehouseId=rng.Next(1,4),productId=rng.Next(1,13),quantity=rng.Next(0,100)};expectedAllowed=actor.Name is "carol" or "dave" or "admin";}
 else if(choice<97){capability="create_shipment";toolArgs=new{actor=actor.Name,orderId=rng.Next(1,Math.Max(2,i+1)),carrierId=rng.Next(1,3),warehouseId=rng.Next(1,4),trackingNumber=$"TRK-{seed}-{i}"};expectedAllowed=actor.Name is "carol" or "admin";}
 else {capability="update_shipment";toolArgs=new{actor=actor.Name,shipmentId=rng.Next(1,Math.Max(2,i+1)),status=new[]{"In Transit","Out for Delivery","Delivered","Delayed"}[rng.Next(4)]};expectedAllowed=actor.Name is "carol" or "admin";}
 try{var before=await CountOrders(db,actor.CustomerId);var body=await Call(http,mcp,capability,toolArgs);sw.Stop();var toolError=IsToolError(body);var after=await CountOrders(db,actor.CustomerId);records.Add(new Record(i+1,actor.Name,capability,expectedAllowed,!toolError,sw.Elapsed.TotalMilliseconds,before,after,body.Length,toolError?body:null));}
 catch(Exception ex){sw.Stop();records.Add(new Record(i+1,actor.Name,capability,expectedAllowed,false,sw.Elapsed.TotalMilliseconds,-1,-1,0,ex.Message));}
}
var report=new{schemaVersion=1,utc=DateTimeOffset.UtcNow,seed,steps,customers,mcp,summary=new{success=records.Count(x=>x.Success),failures=records.Count(x=>!x.Success),expectedAllowed=records.Count(x=>x.ExpectedAllowed),unexpectedSuccesses=records.Count(x=>!x.ExpectedAllowed&&x.Success),avgLatencyMs=records.Where(x=>x.Success).Select(x=>x.LatencyMs).DefaultIfEmpty().Average()},records};await File.WriteAllTextAsync(Path.Combine(reportDir,"supply-chain-report.json"),JsonSerializer.Serialize(report,new JsonSerializerOptions{WriteIndented=true}));await File.WriteAllTextAsync(Path.Combine(reportDir,"supply-chain-report.md"),Markdown(report));Console.WriteLine($"Supply Chain E2E: {report.summary.success}/{steps} successful; unexpected unauthorized successes={report.summary.unexpectedSuccesses}; avg latency={report.summary.avgLatencyMs:F1}ms");

static bool IsToolError(string body){try{using var d=JsonDocument.Parse(body);if(d.RootElement.TryGetProperty("error",out _))return true;if(d.RootElement.TryGetProperty("result",out var r)&&r.TryGetProperty("isError",out var e)&&e.ValueKind==JsonValueKind.True)return true;}catch{}return false;}
static async Task<string> Call(HttpClient http,string url,string name,object args){var req=JsonSerializer.Serialize(new{jsonrpc="2.0",id=Guid.NewGuid().ToString("N"),method="tools/call",@params=new{name,arguments=args}});using var msg=new HttpRequestMessage(HttpMethod.Post,url){Content=new StringContent(req,Encoding.UTF8,"application/json")};msg.Headers.Accept.Add(new MediaTypeWithQualityHeaderValue("application/json"));msg.Headers.Accept.Add(new MediaTypeWithQualityHeaderValue("text/event-stream"));msg.Headers.TryAddWithoutValidation("MCP-Protocol-Version","2025-06-18");using var res=await http.SendAsync(msg);var body=await res.Content.ReadAsStringAsync();if(!res.IsSuccessStatusCode)return $"HTTP {(int)res.StatusCode}: {body}";return body;}
static async Task<int> CountOrders(NpgsqlDataSource ds,int customer){await using var c=await ds.OpenConnectionAsync();await using var q=new NpgsqlCommand("SELECT count(*) FROM orders WHERE customer_id=@c",c);q.Parameters.AddWithValue("c",customer);return Convert.ToInt32(await q.ExecuteScalarAsync());}
static async Task Wait(HttpClient h,string url){for(var i=0;i<120;i++){try{if((await h.GetAsync(url)).IsSuccessStatusCode)return;}catch{}await Task.Delay(500);}throw new InvalidOperationException("MCP service not ready: "+url);}
static int GetInt(string n,int d)=>int.TryParse(Environment.GetEnvironmentVariable(n),out var v)?v:d;
static string Markdown(dynamic r)=>$"# Supply Chain E2E\n\n- Seed: {r.seed}\n- Steps: {r.steps}\n- Customers: {r.customers}\n- Success: {r.summary.success}\n- Failures: {r.summary.failures}\n- Unexpected unauthorized successes: {r.summary.unexpectedSuccesses}\n- Average latency: {r.summary.avgLatencyMs:F1} ms\n";
record Actor(string Name,int CustomerId);record Record(int Step,string Actor,string Capability,bool ExpectedAllowed,bool Success,double LatencyMs,int OrdersBefore,int OrdersAfter,int ResponseBytes,string? Error);
